"""Write an auditable Persian summary from calculated model results."""
import json
import numpy as np
import pandas as pd
from app_core import Dataset
from auto_engine import OUT

def main():
    report=json.loads((OUT/'results.json').read_text(encoding='utf-8'))
    d=Dataset.builtin();records=report['test'];coverage=[]
    def lookup(metric,level,h):return next(r for r in records if r['metric']==metric and r['level']==level and r['horizon']==h)['wape']
    lines=['# نتیجهٔ مدل‌های خودکار RA — ۲۷ اکتبر ۲۰۲۶','',
           'هدف پروژه WAPE حداکثر ۱۰٪ است. WAPE مجموع خطای مطلق تقسیم بر مجموع فروش واقعی است؛ «۱۰۰ منهای WAPE» را نباید تضمینِ دقتِ تک‌تک کالاها یا ماه آینده دانست. کاربر در رابط روش و طول تاریخچه انتخاب نمی‌کند. فایل، مشخصات محصول/شهر، شاخص و ماه مقصد را تعیین می‌کند و سامانه انتخاب و آموزش را انجام می‌دهد.','',
           'دادهٔ ماست شامل ۵۴ ماه از مارس ۲۰۲۲ تا اوت ۲۰۲۶ و ۱۳٬۱۰۴ ترکیب شهر، کمپانی، برند، زیر‌برند و چهار سطح ساب‌کتگوری است. فقط بازار City جمع شده است. در آزمون زیر، آموزش به داده‌های تا مه ۲۰۲۶ محدود بود و ماه‌های مقصد ژوئن، ژوئیه و اوت بودند.','',
           '## خطای بازآزمایی ژوئن تا اوت','',
           '| سطح | شاخص | یک ماه جلو | دو ماه جلو | سه ماه جلو |',
           '|---|---|---:|---:|---:|']
    for level,label in [('city_segment','شهر × ریزترین ترکیب محصول'),('city_subbrand','شهر × کمپانی × برند × زیر‌برند'),('national_segment','کل بازار × ریزترین ترکیب محصول')]:
        for metric,mname in [('volume_kg','حجم'),('value_1000_toman','مبلغ')]:
            vals=[f'{lookup(metric,level,h)*100:.2f}٪' for h in [1,2,3]]
            lines.append('| '+' | '.join([label,mname,*vals])+' |')
    lines+=['','برای سطح شهر × زیر‌برند، همهٔ شش مقدار زیر ۱۰٪ هستند. در ریزترین ترکیب محصول، مبلغِ سه ماه جلو هنوز حدود ۱۰٫۷٪ خطا دارد. بنابراین شرط «حداقل ۹۰٪ برای هر انتخاب و همهٔ افق‌ها» اثبات نشده است.','',
            '## روش‌های مقایسه‌شده','',
            'آخرین ماه، میانگین‌های ۲/۳/۶ ماه، هموارسازی نمایی، ماه مشابه سال قبل، روند کنترل‌شده، روند قیمت در ۲/۳/۶ ماه، سه نوع هدف CatBoost (تغییر خام، تغییر مقیاس‌شده و نسبت لگاریتمی)، مدل جداگانهٔ قیمت و حجم و ترکیب‌های ثابت مدل و روش پایه مقایسه شدند. مدل‌های سراسری از تاریخچهٔ ۲۴ ماه یا همهٔ ماه‌های موجود استفاده کردند و با همهٔ سری‌های شهر/محصول یاد گرفتند. تقویم، فروش‌های قبلی، قیمت واحدِ قبلی، روندها و سهم در والدها ورودی بودند. مقدار آیندهٔ قیمت، دلار یا توزیع وارد آموزش نشد.','',
            'انتخاب اولیه بر سه مبدأ مه ۲۰۲۵، سپتامبر ۲۰۲۵ و فوریهٔ ۲۰۲۶ انجام شد؛ آخرین مقصد انتخاب، مه ۲۰۲۶ بود. خطای انتخاب قبل از اصلاح جهش قیمت، برای حجم در افق‌های ۱/۲/۳ حدود ۸٫۶/۹٫۷/۱۱٫۶٪ و برای مبلغ ۱۰٫۲/۱۲٫۳/۱۸٫۶٪ بود. این تغییر خطا بین مقطع‌ها نشان می‌دهد نتیجهٔ خوبِ آخرین سه ماه را نمی‌توان به همهٔ دوره‌ها تعمیم داد.','',
            '## مشکل جهش قیمت و اصلاح آن','',
            'نسخهٔ اولیهٔ مدل‌های پیچیده در مبلغ، رشد شدید قیمت را ادامه می‌داد و در آزمون ژوئن/ژوئیه/اوت حدود ۱۴٫۵/۲۴٫۰/۲۵٫۱٪ خطا داشت. این نتیجه به‌عنوان نسخهٔ بهبودیافته پذیرفته نشد. فایل‌های کامل آن در `unprotected_v1/` نگه داشته شده‌اند.','',
            'کنترل تغییر سطح به این صورت عمل می‌کند: ارزش واحد تجمیعی = مبلغ کل ÷ حجم کل. اگر تغییر ماه جاری بیش از سه MAD مقیاس‌شده از میانهٔ ۲۴ تغییر قبلی فاصله داشته باشد، با حداقل فاصلهٔ پنج واحد درصد، جهش غیرعادی محسوب می‌شود. در این حالت قیمت تازه حفظ می‌شود و برای رشد بعدی، میانهٔ تغییرات قبلی به‌کار می‌رود. مقدار فروش از ترکیب ثابت ۵۰٪ مدل حجمی و ۵۰٪ آخرین حجم مشاهده‌شده برآورد می‌شود. وزن‌ها از هدف‌های ریالیِ بعدی برازش نشده‌اند. این ارزش واحد، نمایندهٔ قیمت و ترکیب محصول است و معادل تورم رسمی نیست.','',
            f'در مه ۲۰۲۶ تغییر ارزش واحد {report["plan"]["price_shift_guard"]["current_change"]*100:.2f}٪ بود و میانهٔ ۲۴ تغییر قبلی {report["plan"]["price_shift_guard"]["median_prior_change"]*100:.2f}٪. دادهٔ بعد از مه برای تشخیص این جهش استفاده نشده است.','',
            '**محدودیت مهم ارزیابی:** این اصلاح پس از دیدن ضعف نسخهٔ قبلی انجام شد و ژوئن تا اوت در توسعه چند بار بررسی شده‌اند. جدول بالا «بازآزمایی پس‌نگر» است و آزمون نهاییِ دست‌نخورده یا اثبات دقت ۹۰٪ در آینده نیست. تأیید واقعی به گزارش‌هایی نیاز دارد که هنگام صدور پیش‌بینی در دسترس نبوده‌اند.','',
            '## اختلاف دقت بین محصولات','',
            'جدول زیر سهم ترکیب‌های دارای فروش واقعی مثبت را نشان می‌دهد که خطای مجموع سه‌ماههٔ آن‌ها حداکثر ۱۰٪ بوده است. صفرهای واقعی در محاسبهٔ WAPE کل همچنان لحاظ شده‌اند.','',
            '| شاخص | سطح | تعداد ترکیب مثبت | درصد تعداد با خطای ≤۱۰٪ | سهم فروش واقعی با خطای ≤۱۰٪ |',
            '|---|---|---:|---:|---:|']
    for metric,label in [('volume_kg','حجم'),('value_1000_toman','مبلغ')]:
        with np.load(OUT/(metric+'_final.npz')) as z:y=z['actual'];p=z['prediction']
        for cols,level in [(list(range(8)),'ریزترین ترکیب شهری/محصولی'),([0,1,2,3],'شهر × زیر‌برند')]:
            meta=pd.DataFrame(d.meta[:,cols]);ids=meta.groupby(list(meta.columns),sort=False).ngroup().to_numpy()
            yy=np.zeros((ids.max()+1,3));pp=np.zeros_like(yy);np.add.at(yy,ids,y);np.add.at(pp,ids,p)
            total=yy.sum(1);err=abs(pp-yy).sum(1);pos=total>0;good=pos&(err<=.1*total)
            row={'metric':metric,'level':level,'positive_groups':int(pos.sum()),'group_share_below_10':float(good.sum()/pos.sum()),'sales_share_below_10':float(total[good].sum()/total.sum())}
            coverage.append(row)
            lines.append(f'| {label} | {level} | {row["positive_groups"]} | {row["group_share_below_10"]*100:.1f}٪ | {row["sales_share_below_10"]*100:.1f}٪ |')
    lines+=['','## استفاده در رابط','',
            'با فایل فعلی، ماه‌های مقصد سپتامبر، اکتبر و نوامبر ۲۰۲۶ هستند؛ در فایل برای آن‌ها مقدار واقعی وجود ندارد. مدل‌های لازم روی داده‌های تا اوت آموزش می‌بینند. انتخاب زمان اجرا با ماه‌های تکمیل‌شدهٔ همان فایل بازبینی می‌شود و نتایج آموزش ذخیره می‌شود. برخی ماه‌ها با توجه به تأخیر انتشار RA از نظر تقویمی گذشته‌اند ولی هنوز دادهٔ گزارششان موجود نیست.','',
            'سرتیترهای مشابه، جابه‌جایی ستون‌ها و واحدهای متفاوت شناسایی می‌شوند؛ برای نام ناشناخته فرم نگاشت نمایش داده می‌شود. آزمون ساختار با فایل ساختگی شیر انجام شده است و به معنی تأیید دقت پیش‌بینی شیر نیست. برای هر دستهٔ واقعی باید آزمون‌های همان دسته انجام شود.','',
            'فایل‌های `validation.csv`، `test_results.csv`، `policy.json` و `plan.json` اعداد و قواعد را نگه می‌دارند. آزمون تغییر دادن مقادیر ماه‌های بعد از مبدأ ثابت کرد خروجی‌ها و تشخیص جهش تغییر نمی‌کنند. درخواست ماه آینده، سری‌های ثابت، سری‌های تماماً صفر و افق نامعتبر نیز بررسی شدند.','',
            'پیش‌بینی‌های سپتامبر، اکتبر و نوامبر برای همهٔ ترکیب‌ها و هر دو شاخص در `issued/2026-08_robust-price-volume-v3.npz` ثبت شده‌اند. فایل JSON کنار آن زمان صدور، روش‌ها و SHA-256 را ثبت کرده است. پس از دریافت گزارش واقعی باید همین اعدادِ ثبت‌شده با آن مقایسه شوند؛ اسکریپت صدور، فایل موجود را بازنویسی نمی‌کند.','']
    (OUT/'REPORT_FA.md').write_text('\n'.join(lines),encoding='utf-8')
    (OUT/'coverage.json').write_text(json.dumps(coverage,ensure_ascii=False,indent=2),encoding='utf-8')
    print('Report and coverage saved.')

if __name__=='__main__':main()
